def solve_all_p():
    max_a = 0
    for k in range(1, 1000):
        for p1 in range(1000):
            l = 1000 - p1
            if l > 0 and p1 <= k * l:
                a = p1 - k + 1
                if a > max_a:
                    max_a = a
    return max_a

print(solve_all_p())
